import{_ as a,o as i,c as r,a2 as t}from"./chunks/framework.ChIlRNAd.js";const y=JSON.parse('{"title":"Privacy","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/privacy.md","filePath":"en/guide/privacy.md"}'),n={name:"en/guide/privacy.md"};function o(s,e,c,l,p,h){return i(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="privacy" tabindex="-1">Privacy <a class="header-anchor" href="#privacy" aria-label="Permalink to &quot;Privacy&quot;">​</a></h1><p>Nid can encrypt your archives. Remote images (and the tracking pixels they hide) are blocked by the mail reader until you show them.</p><hr><h2 id="archive-encryption" tabindex="-1">Archive Encryption <a class="header-anchor" href="#archive-encryption" aria-label="Permalink to &quot;Archive Encryption&quot;">​</a></h2><p>Your EML archives can be encrypted on the NAS using <strong>AES-256-GCM</strong> encryption (the same standard used by banks and governments).</p><h3 id="configure-encryption" tabindex="-1">Configure Encryption <a class="header-anchor" href="#configure-encryption" aria-label="Permalink to &quot;Configure Encryption&quot;">​</a></h3><ol><li>In the <strong>Encryption</strong> tab, click <strong>Configure</strong></li><li>Choose a <strong>passphrase</strong></li><li>Confirm the passphrase</li><li>Click <strong>Enable encryption</strong></li></ol><blockquote><p>📸 <em>Suggested screenshot: encryption configuration form with the passphrase field</em></p></blockquote><div class="warning custom-block"><p class="custom-block-title">Keep your passphrase safe</p><p>The passphrase is <strong>never stored</strong> in the application — only a verification hash is kept. If you lose it, it will be impossible to decrypt your archives. Write it down in a safe place (password manager, etc.).</p></div><h3 id="encrypt-existing-archives" tabindex="-1">Encrypt Existing Archives <a class="header-anchor" href="#encrypt-existing-archives" aria-label="Permalink to &quot;Encrypt Existing Archives&quot;">​</a></h3><p>After configuring the passphrase:</p><ol><li>Click <strong>Encrypt archives</strong></li><li>An encryption job is launched</li><li>Each EML file is individually encrypted on disk</li></ol><p>Already encrypted emails are automatically skipped (idempotent).</p><h3 id="read-an-encrypted-email" tabindex="-1">Read an Encrypted Email <a class="header-anchor" href="#read-an-encrypted-email" aria-label="Permalink to &quot;Read an Encrypted Email&quot;">​</a></h3><p>When you view an encrypted email on the Archives page, it is <strong>decrypted on the fly</strong> in server memory. The file remains encrypted on disk at all times.</p><h3 id="encryption-status" tabindex="-1">Encryption Status <a class="header-anchor" href="#encryption-status" aria-label="Permalink to &quot;Encryption Status&quot;">​</a></h3><p>The Encryption tab displays:</p><ul><li>Whether a passphrase is configured</li><li>The number of encrypted / unencrypted emails</li><li>An overall security indicator</li></ul><blockquote><p>📸 <em>Suggested screenshot: encryption status with the number of encrypted emails and percentage</em></p></blockquote>',19)])])}const u=a(n,[["render",o]]);export{y as __pageData,u as default};
